document.addEventListener("DOMContentLoaded", function() {
    // Lógica del menú móvil (Hamburguesa)
    const menuToggle = document.querySelector(".menu-toggle");
    const navMenu = document.querySelector(".nav-menu");
    const navLinks = document.querySelectorAll(".nav-menu a");

    if (menuToggle && navMenu) {
        menuToggle.addEventListener("click", function() {
            menuToggle.classList.toggle("active");
            navMenu.classList.toggle("active");
        });

        // Cerrar menú al hacer clic en un enlace
        navLinks.forEach(link => {
            link.addEventListener("click", function() {
                menuToggle.classList.remove("active");
                navMenu.classList.remove("active");
            });
        });

        // Cerrar menú al hacer clic fuera
        document.addEventListener("click", function(e) {
            if (!navMenu.contains(e.target) && !menuToggle.contains(e.target) && navMenu.classList.contains("active")) {
                menuToggle.classList.remove("active");
                navMenu.classList.remove("active");
            }
        });
    }

    // Efecto de scroll en la barra de navegación
    const nav = document.querySelector("nav");
    let ticking = false;

    function handleMobileNavOnScroll(isMobile, scrollPos) {
        if (!nav) return;
        if (isMobile && scrollPos > 0) {
            nav.classList.add("nav-mobile-scrolled");
        } else {
            nav.classList.remove("nav-mobile-scrolled");
        }
    }

    document.addEventListener("scroll", function() {
        if (!ticking) {
            window.requestAnimationFrame(() => {
                handleMobileNavOnScroll(window.innerWidth <= 979, window.scrollY);
                ticking = false;
            });
            ticking = true;
        }
    });

    // Inicialización
    handleMobileNavOnScroll(window.innerWidth <= 979, window.scrollY);
    window.addEventListener("resize", () => handleMobileNavOnScroll(window.innerWidth <= 979, window.scrollY));
});
